{{ get_solua_print_css() }}{% set p = get_wholesale_print_data(doc) %}{% set company = p.company %}{% set customer = p.customer %}{% set show_item_name = doc.get('custom_print_item_name') if doc.get('custom_print_item_name') is not none else 1 %}{% set show_sku = doc.get('custom_print_sku') if doc.get('custom_print_sku') is not none else 1 %}{% set show_color_code = doc.get('custom_print_color_code') if doc.get('custom_print_color_code') is not none else 1 %}{% set show_cor = doc.get('custom_print_cor') if doc.get('custom_print_cor') is not none else 0 %}{% set show_description = doc.get('custom_print_description') if doc.get('custom_print_description') is not none else 1 %}
<h2>Confirmação de Encomenda / 订单确认单</h2>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — Documento não oficial / 非正式凭证</div>{% endif %}
{% if p.get('legacy') %}<div class="warning">Documento histórico sem snapshot de impressão; dados complementares do cadastro atual. / 历史单据未保存打印快照；补充资料来自当前主档。</div>{% endif %}
<table class="meta"><tr><td><b>{{ company.name | e }}</b><br>NUIT: {{ company.nuit | e }}<br>{{ company.address }}<br>Tel: {{ company.phone | e }}</td><td><b>Cliente / 客户: {{ customer.name | e }}</b><br>NUIT: {{ customer.nuit or 'Não informado / 未提供' | e }}<br>Loja / 门店: {{ customer.store | e }}<br>{{ customer.address }}<br>{{ customer.contact }} · {{ customer.phone | e }}</td></tr><tr><td>N.º / 编号: {{ doc.name | e }}<br>N.º encomenda cliente / 客户订单号: {{ doc.get('custom_customer_order_no') or '—' | e }}</td><td>Data / 日期: {{ doc.get('posting_date') or doc.get('transaction_date') }}<br>Prazo de entrega / 交期: {{ doc.get('delivery_date') or '—' }}</td></tr></table>
<table class="items"><thead><tr><th colspan="{{ 5 + show_item_name + show_sku + show_color_code + show_cor + show_description }}">{{ doc.name | e }} · 订购 / Encomenda</th></tr><tr>{% if show_item_name %}<th class="col-item">Artigo / 商品</th>{% endif %}{% if show_sku %}<th class="col-sku">SKU / 货号</th>{% endif %}{% if show_color_code %}<th class="col-color-code">Código de cor fixo / 固定色号</th>{% endif %}{% if show_cor %}<th class="col-cor">Cor / 颜色</th>{% endif %}<th class="col-barcode">条码 / Código de barras</th>{% if show_description %}<th class="col-description">描述 / Descrição</th>{% endif %}<th>Quantidade encomendada / 订购数量</th><th class="col-uom">Un.</th><th class="col-rate">Preço /<br>单价</th><th class="col-amount">Valor / 金额</th></tr></thead><tbody>
{% for item in p['items'] %}<tr>{% if show_item_name %}<td>{% if doc.get('custom_print_color_images') and item.image %}<img class="photo" src="{{ item.image | e }}"><br>{% endif %}{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td class="col-sku">{{ (item.order_code or item.item_code) | e }}{% if item.order_code and item.item_code and item.order_code != item.item_code %}<br><small>{{ item.item_code | e }}</small>{% endif %}</td>{% endif %}{% if show_color_code %}<td class="col-color-code">{{ (item.color_code or '—') | e }}</td>{% endif %}{% if show_cor %}<td class="col-cor">{{ (item.color or '—') | e }}</td>{% endif %}<td class="col-barcode">{{ (item.get('barcode') or '—') | e }}</td>{% if show_description %}<td class="col-description">{{ (item.get('description') or '—') | e }}</td>{% endif %}<td class='col-qty num'>{{ format_print_qty(item.qty) }}</td><td class="col-uom">{{ item.uom | e }}</td><td class="num">{{ format_print_money(item.rate, currency=doc.currency) }}</td><td class="num">{{ format_print_money(item.amount, currency=doc.currency) }}</td></tr>{% endfor %}
</tbody><tfoot><tr><td colspan='{{ 1 + show_item_name + show_sku + show_color_code + show_cor + show_description }}' style='text-align:right'><b>Total Qty / 总数量</b></td><td style='text-align:right'><b>{{ format_print_qty(get_print_total_qty(p)) }}</b></td><td colspan='3'></td></tr></tfoot></table><div class="block num">Total / 含税合计: {{ format_print_money(doc.grand_total, currency=doc.currency) }}</div>
<div class="block">Plano de pagamento / 付款安排: {{ p.payment_method or '未维护' | e }} · Depósito / 定金: {{ format_print_money(p.deposit, currency=doc.currency) }} · Vencimento do saldo / 尾款到期: {{ p.balance_due_date or '—' | e }}<br>Plano de faturação / 开票安排: {{ p.invoice_plan or '未维护' | e }}</div>
{% if doc.get('payment_schedule') %}<table><thead><tr><th>Condições de pagamento / 付款条件</th><th>Data de vencimento / 到期日</th><th>Valor / 金额</th></tr></thead><tbody>{% for row in doc.payment_schedule %}<tr><td>{{ row.payment_term or '' | e }}</td><td>{{ row.due_date }}</td><td>{{ format_print_money(row.payment_amount, currency=doc.currency) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if doc.get('custom_print_color_qr') %}{% set seen = [] %}<div class="block">{% for item in p['items'] %}{% if item.template_code and item.template_code not in seen %}{% set unused = seen.append(item.template_code) %}{% set qr = get_color_card_qr_img(item.template_code) %}{% if qr %}<img class="qr" src="{{ qr | e }}">{{ item.template_code | e }} {% endif %}{% endif %}{% endfor %}</div>{% endif %}
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>

css:
@page{size:A4;margin:12mm}.print-format{font-size:var(--solua-font-size);color:#263238}h2{font-size:20px;color:#99732c}table{width:100%;border-collapse:collapse;table-layout:auto;margin:10px 0}table.items{table-layout:auto}th,td{padding:var(--solua-cell-padding);border-bottom:1px solid #ddd;vertical-align:top;overflow-wrap:normal}th{background:#f5f1e9}thead{display:table-header-group}tr{page-break-inside:avoid}.meta td{width:50%}.num{text-align:right}.photo{max-width:45px;max-height:45px}.block{page-break-inside:avoid;margin-top:12px}.sign{height:95px;border:1px solid #bbb;padding:8px}.warning{color:#a35c00}.qr{height:60px;width:60px}
.print-format table.items, .print-format table.wholesale-items { table-layout: auto; }
.print-format table.items th, .print-format table.items td,
.print-format table.wholesale-items th, .print-format table.wholesale-items td { overflow-wrap: normal; word-break: normal; }
.print-format .items .col-item { min-width: 24mm; }
.print-format .items .col-sku { min-width: 27mm; white-space: nowrap; }
.print-format .items .col-color-code, .print-format .items .col-cor { min-width: 16mm; white-space: nowrap; }
.print-format .items .col-barcode { min-width: 31mm; white-space: nowrap; }
.print-format .items .col-description { min-width: 42mm; white-space: normal; overflow-wrap: break-word; word-break: normal; }
.print-format .items .col-qty, .print-format .items .col-uom,
.print-format .items .col-rate, .print-format .items .col-amount { white-space: nowrap; }

.print-format .items .col-item, .print-format .wholesale-items .col-item { min-width: 24mm; }
.print-format .items .col-sku, .print-format .wholesale-items .col-sku { min-width: 27mm; white-space: nowrap; }
.print-format .items .col-color-code, .print-format .items .col-cor,
.print-format .wholesale-items .col-color-code, .print-format .wholesale-items .col-cor { min-width: 16mm; white-space: nowrap; }
.print-format .items .col-barcode, .print-format .wholesale-items .col-barcode { min-width: 31mm; white-space: nowrap; }
.print-format .items .col-description, .print-format .wholesale-items .col-description { min-width: 42mm; white-space: normal; overflow-wrap: break-word; word-break: normal; }
.print-format .items .col-qty, .print-format .items .col-uom, .print-format .items .col-rate, .print-format .items .col-amount,
.print-format .wholesale-items .col-qty, .print-format .wholesale-items .col-uom, .print-format .wholesale-items .col-rate, .print-format .wholesale-items .col-amount { white-space: nowrap; }
